select public.admin_save_question('{"id":"allgemeinwissen-chemisches-element","packId":"allgemeinwissen","prompt":"Nenne ein chemisches Element.","topic":"Wissenschaft","difficulty":1,"timeLimitSeconds":null,"status":"verified","sources":[{"label":"Wikipedia: Periodensystem","url":"https://de.wikipedia.org/wiki/Periodensystem"}],"notes":"Seed-Inhalt: redaktionell zusammengestellt, Seltenheit redaktionell eingestuft.","answers":[{"id":"allgemeinwissen-chemisches-element:sauerstoff","text":"Sauerstoff","aliases":["O","Oxygen","Oxygenium"],"tier":"known","explanation":"Element 8 – macht rund 21 % der Erdatmosphäre aus.","source":null,"status":"verified"},{"id":"allgemeinwissen-chemisches-element:wasserstoff","text":"Wasserstoff","aliases":["H","Hydrogen","Hydrogenium"],"tier":"known","explanation":"Element 1 – das häufigste Element im Universum.","source":null,"status":"verified"},{"id":"allgemeinwissen-chemisches-element:gold","text":"Gold","aliases":["Au","Aurum"],"tier":"known","explanation":"Element 79, Symbol Au vom lateinischen „aurum“.","source":null,"status":"verified"},{"id":"allgemeinwissen-chemisches-element:eisen","text":"Eisen","aliases":["Fe","Ferrum"],"tier":"known","explanation":"Element 26 – Hauptbestandteil des Erdkerns.","source":null,"status":"verified"},{"id":"allgemeinwissen-chemisches-element:kohlenstoff","text":"Kohlenstoff","aliases":["C","Carbon","Carboneum"],"tier":"known","explanation":"Element 6 – Grundlage allen bekannten Lebens.","source":null,"status":"verified"},{"id":"allgemeinwissen-chemisches-element:stickstoff","text":"Stickstoff","aliases":["N","Nitrogen","Nitrogenium"],"tier":"familiar","explanation":"Element 7 – rund 78 % der Luft bestehen daraus.","source":null,"status":"verified"},{"id":"allgemeinwissen-chemisches-element:helium","text":"Helium","aliases":["He"],"tier":"familiar","explanation":"Element 2 – Edelgas, leichter als Luft.","source":null,"status":"verified"},{"id":"allgemeinwissen-chemisches-element:silber","text":"Silber","aliases":["Ag","Argentum"],"tier":"familiar","explanation":"Element 47 – leitet Strom besser als jedes andere Metall.","source":null,"status":"verified"},{"id":"allgemeinwissen-chemisches-element:kupfer","text":"Kupfer","aliases":["Cu","Cuprum"],"tier":"familiar","explanation":"Element 29 – seit über 10 000 Jahren genutzt.","source":null,"status":"verified"},{"id":"allgemeinwissen-chemisches-element:uran","text":"Uran","aliases":["U","Uranium"],"tier":"unusual","explanation":"Element 92 – benannt nach dem Planeten Uranus.","source":null,"status":"verified"},{"id":"allgemeinwissen-chemisches-element:neon","text":"Neon","aliases":["Ne"],"tier":"unusual","explanation":"Element 10 – leuchtet in Gasentladungsröhren rot-orange.","source":null,"status":"verified"},{"id":"allgemeinwissen-chemisches-element:titan","text":"Titan","aliases":["Ti","Titanium"],"tier":"unusual","explanation":"Element 22 – leicht, fest und korrosionsbeständig.","source":null,"status":"verified"},{"id":"allgemeinwissen-chemisches-element:wolfram","text":"Wolfram","aliases":["W","Tungsten"],"tier":"rare","explanation":"Element 74 – Metall mit dem höchsten Schmelzpunkt.","source":null,"status":"verified"},{"id":"allgemeinwissen-chemisches-element:gallium","text":"Gallium","aliases":["Ga"],"tier":"rare","explanation":"Element 31 – schmilzt bereits bei knapp 30 °C in der Hand.","source":null,"status":"verified"},{"id":"allgemeinwissen-chemisches-element:bismut","text":"Bismut","aliases":["Bi","Wismut"],"tier":"rare","explanation":"Element 83 – bildet farbig schillernde Treppenkristalle.","source":null,"status":"verified"},{"id":"allgemeinwissen-chemisches-element:ytterbium","text":"Ytterbium","aliases":["Yb"],"tier":"very_rare","explanation":"Element 70 – einer von vier Elementnamen, die auf das schwedische Dorf Ytterby zurückgehen.","source":null,"status":"verified"},{"id":"allgemeinwissen-chemisches-element:praseodym","text":"Praseodym","aliases":["Pr","Praseodymium"],"tier":"very_rare","explanation":"Element 59 – ein Seltenerdmetall, färbt Glas grün.","source":null,"status":"verified"},{"id":"allgemeinwissen-chemisches-element:oganesson","text":"Oganesson","aliases":["Og"],"tier":"legendary","explanation":"Element 118 – das schwerste bisher benannte Element, nach Juri Oganessjan.","source":null,"status":"verified"},{"id":"allgemeinwissen-chemisches-element:rutherfordium","text":"Rutherfordium","aliases":["Rf"],"tier":"legendary","explanation":"Element 104 – künstlich erzeugt, nach Ernest Rutherford benannt.","source":null,"status":"verified"}],"wrongAnswers":[{"text":"Wasser","explanation":"Wasser ist eine Verbindung (H₂O) aus Wasserstoff und Sauerstoff – kein Element.","aliases":[]},{"text":"Stahl","explanation":"Stahl ist eine Legierung, vor allem aus Eisen und Kohlenstoff.","aliases":[]},{"text":"Bronze","explanation":"Bronze ist eine Legierung aus Kupfer und Zinn.","aliases":[]}],"createdAt":"2026-11-01T00:00:00.000Z","updatedAt":"2026-11-01T00:00:00.000Z"}'::jsonb);
